// Validates a PMS request and turns it into one read-only Smoobu call.
// Anything not on these allowlists is rejected before Smoobu is contacted.
// Smoobu is the channel manager and PriceLabs writes prices through it, so the
// gateway only ever reads (GET).
const body = $json.body || {};
const RESERVATION_QUERY = ['from', 'to', 'created_from', 'created_to', 'modifiedFrom', 'modifiedTo', 'arrivalFrom', 'arrivalTo', 'departureFrom', 'departureTo', 'showCancellation', 'excludeBlocked', 'apartmentId', 'includeRelated', 'includePriceElements', 'page', 'pageSize'];
const PATHS = [
  { pattern: /^\/api\/apartments$/, query: [] },
  { pattern: /^\/api\/apartments\/\d{1,12}$/, query: [] },
  { pattern: /^\/api\/reservations$/, query: RESERVATION_QUERY },
  { pattern: /^\/api\/reservations\/\d{1,12}$/, query: [] },
  { pattern: /^\/api\/reservations\/\d{1,12}\/price-elements$/, query: [] },
  { pattern: /^\/api\/threads$/, query: ['page_number', 'page_size'] },
];
const reject = (error) => [{ json: { ok: false, status: 400, error } }];

const path = typeof body.path === 'string' ? body.path : '';
const rule = PATHS.find((item) => item.pattern.test(path));
if (!rule) return reject('Path not allowed: ' + (path || '(none)'));

const query = {};
for (const [name, value] of Object.entries(body.query || {})) {
  if (!rule.query.includes(name)) return reject('Query parameter not allowed for ' + path + ': ' + name);
  if (!['string', 'number', 'boolean'].includes(typeof value) || String(value).length > 100) return reject('Bad value for ' + name);
  query[name] = String(value);
}
return [{ json: { ok: true, path, query, useSignedKey: $json.useSignedKey === true } }];

// Calls Smoobu with the signed HMAC key (needed from 31 October 2026, when the
// old Api-Key header stops). n8n credentials can't sign requests, so the key and
// secret come from n8n Variables: SMOOBU_API_KEY and SMOOBU_API_SECRET.
// Answers in the same shape as the old-key HTTP node: { statusCode, headers, body }.
const crypto = require('crypto');

const key = $vars.SMOOBU_API_KEY;
const secret = $vars.SMOOBU_API_SECRET;
if (!key || !secret) throw new Error('Add the n8n Variables SMOOBU_API_KEY and SMOOBU_API_SECRET (Overview > Variables).');

const { path, query } = $json;
// RFC 3986: spaces as %20, and ! ' ( ) * escaped too.
const encode = (value) => encodeURIComponent(value).replace(/[!'()*]/g, (c) => '%' + c.charCodeAt(0).toString(16).toUpperCase());
const qs = Object.entries(query || {})
  .map(([name, value]) => [encode(name), encode(String(value))])
  .sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : a[1] < b[1] ? -1 : a[1] > b[1] ? 1 : 0))
  .map(([name, value]) => name + '=' + value)
  .join('&');

// Canonical string, one part per line: method, path, query sorted by key,
// timestamp, nonce, SHA-256 of the body (hex), API key. Signed with the secret.
const timestamp = new Date().toISOString().replace(/\.\d{3}Z$/, 'Z');
const nonce = crypto.randomUUID();
const bodyHash = crypto.createHash('sha256').update('').digest('hex');
const canonical = ['GET', path, qs, timestamp, nonce, bodyHash, key].join('\n');
const signature = crypto.createHmac('sha256', secret).update(canonical).digest('base64');

const response = await this.helpers.httpRequest({
  method: 'GET',
  url: 'https://login.smoobu.com' + path + (qs ? '?' + qs : ''),
  headers: { Accept: 'application/json', 'X-API-Key': key, 'X-Timestamp': timestamp, 'X-Nonce': nonce, 'X-Signature': signature },
  json: true,
  returnFullResponse: true,
  ignoreHttpStatusErrors: true,
  timeout: 30000,
});
return [{ json: { statusCode: response.statusCode, headers: response.headers || {}, body: response.body ?? null } }];
